class Base {
    public:
        virtual void virtualFunction() { /* implementation */ }  // Declares a virtual function
};

class Derived : public Base {
    public:
        void virtualFunction() override { /* overridden implementation */ }  // Overrides the virtual function
};

// Implementation note: The compiler adds a vptr to Base and Derived objects, and the vtable is generated for each class with virtual functions.

code_example:
#include <iostream>

class Base {
public:
    virtual void show() { std::cout << "Base class" << std::endl; }  // Virtual function
};

class Derived : public Base {
public:
    void show() override { std::cout << "Derived class" << std::endl; }  // Overridden virtual function
};

int main() {
    Base* ptr = new Derived();  // Pointer to Base, pointing to Derived object
    ptr->show();  // Runtime polymorphism: Calls Derived::show()
    delete ptr;
    return 0;
}
